// CheckURL checks a webhook URL before it is saved: an absolute https URL without user information, whose host is or resolves
// only to public addresses.
func (s *Service) CheckURL(ctx context.Context, raw string) error {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" || u.Host == "" || u.User != nil {
		return fmt.Errorf("%w: use an absolute https URL without a user name or password", ErrInvalidURL)
	}
	if err := s.checkHost(ctx, u.Hostname()); err != nil {
		return fmt.Errorf("%w: %v", ErrInvalidURL, err)
	}
	return nil
}

// errNotPublic is returned when a host is, or resolves to, an address that is not public.
var errNotPublic = errors.New("the endpoint's address is not public")

// nonPublic are the address ranges a webhook must not be sent to: loopback, private, link-local, carrier-grade NAT, "this
// network", unspecified, multicast and broadcast.
var nonPublic = []netip.Prefix{
	netip.MustParsePrefix("0.0.0.0/8"),
	netip.MustParsePrefix("10.0.0.0/8"),
	netip.MustParsePrefix("100.64.0.0/10"),
	netip.MustParsePrefix("127.0.0.0/8"),
	netip.MustParsePrefix("169.254.0.0/16"),
	netip.MustParsePrefix("172.16.0.0/12"),
	netip.MustParsePrefix("192.168.0.0/16"),
	netip.MustParsePrefix("224.0.0.0/4"),
	netip.MustParsePrefix("255.255.255.255/32"),
	netip.MustParsePrefix("::/128"),
	netip.MustParsePrefix("::1/128"),
	netip.MustParsePrefix("fc00::/7"),
	netip.MustParsePrefix("fe80::/10"),
	netip.MustParsePrefix("ff00::/8"),
}

// publicAddr reports whether ip is a public address. An IPv4 address written as IPv6 is judged as the IPv4 address it holds.
func publicAddr(ip netip.Addr) bool {
	ip = ip.Unmap()
	if !ip.IsValid() {
		return false
	}
	for _, p := range nonPublic {
