// checkHost checks that host is, or resolves only to, public addresses. An IP address is checked as it is; a name is looked up
// with the Resolver, so a DNS answer is checked each time it is needed.
func (s *Service) checkHost(ctx context.Context, host string) error {
	if ip, err := netip.ParseAddr(host); err == nil {
		if !publicAddr(ip) {
			return fmt.Errorf("%w: %s", errNotPublic, ip)
		}
		return nil
	}
	addrs, err := s.resolver.LookupIPAddr(ctx, host)
	if err != nil || len(addrs) == 0 {
		return fmt.Errorf("the host %q does not resolve", host)
	}
	for _, a := range addrs {
		ip, ok := netip.AddrFromSlice(a.IP)
		if !ok || !publicAddr(ip) {
			return fmt.Errorf("%w: %s resolves to %s", errNotPublic, host, a.IP)
		}
	}
	return nil
}

